<?php require 'partials.php';$code=preg_replace('/\D/','',$_GET['code']??'');$s=db()->prepare("SELECT g.*,q.title FROM games g JOIN quizzes q ON q.id=g.quiz_id WHERE g.code=? AND g.status!='finished'");$s->bind_param('s',$code);$s->execute();$g=$s->get_result()->fetch_assoc();$error=$code&&!$g?'Ingen aktiv Jolt har den koden.':'';page_top('Gå med');?>
<?php if(!$g):?><section class="join-page"><form class="join-card" action="play.php"><h1>Gå med i en Jolt</h1><?php if($error):?><p class="error"><?=$error?></p><?php endif?><label>Jolt-kod</label><input name="code" inputmode="numeric" maxlength="6" required><button>Fortsätt →</button></form></section><?php else:?><section class="join-page"><form id="joinForm" class="join-card"><span class="eyebrow">DU GÅR MED I</span><h1><?=e($g['title'])?></h1><input type="hidden" name="code" value="<?=$code?>"><?php if($g['allow_profiles']):?><label>Välj avatar</label><div class="avatars"><?php foreach(['⚡','🦊','🐼','🐸','🦄','🚀'] as $i=>$a):?><label><input type="radio" name="avatar" value="<?=$a?>" <?=$i?'':'checked'?>><?=$a?></label><?php endforeach?></div><label>Ditt namn</label><input name="name" maxlength="40" required placeholder="Quizmästaren"><?php else:?><input type="hidden" name="avatar" value="⚡"><input type="hidden" name="name" value="Spelare <?=random_int(10,99)?>"><?php endif?><button>Gå med ⚡</button></form></section><script src="assets/join.js"></script><?php endif?><?php page_bottom();?>

